test("packed artifact contains an executable pi-intercom bin and its runtime modules", () => {
  const temp = mkdtempSync(join(process.cwd(), ".pi-intercom-pack-"));
  const cache = join(temp, "npm-cache");
  const extracted = join(temp, "extracted");
  mkdirSync(cache);
  mkdirSync(extracted);
  try {
    const npmArgs = ["--ignore-scripts", "--cache", cache, "--json"];
    const dryRun = JSON.parse(execFileSync("npm", ["pack", "--dry-run", ...npmArgs], { encoding: "utf8" })) as Array<{ files: Array<{ path: string }> }> | Record<string, { files: Array<{ path: string }> }>;
    const dryRunPackage = Array.isArray(dryRun) ? dryRun[0]! : Object.values(dryRun)[0]!;
    const dryRunFiles = new Set(dryRunPackage.files.map((file) => file.path));
    for (const path of [
      "cli.mjs",
      "cli.ts",
      "cross-machine-discovery.ts",
      "cross-machine-envelope.ts",
      "cross-machine-transport.ts",
      "broker/client.ts",
      "package.json",
    ]) {
      assert.equal(dryRunFiles.has(path), true, `dry-run omitted ${path}`);
    }

    const packed = JSON.parse(execFileSync("npm", ["pack", "--pack-destination", temp, ...npmArgs], { encoding: "utf8" })) as Array<{ filename: string }> | Record<string, { filename: string }>;
    const packedPackage = Array.isArray(packed) ? packed[0]! : Object.values(packed)[0]!;
    const tarball = join(temp, packedPackage.filename);
    const tarFiles = execFileSync("tar", ["-tzf", tarball], { encoding: "utf8" }).trim().split("\n");
    assert.equal(tarFiles.includes("package/cli.mjs"), true);
    execFileSync("tar", ["-xzf", tarball, "-C", extracted]);

    const packageRoot = join(extracted, "package");
    const manifest = JSON.parse(readFileSync(join(packageRoot, "package.json"), "utf8")) as { bin?: Record<string, string> };
    assert.equal(manifest.bin?.["pi-intercom"], "cli.mjs");
    const executable = join(packageRoot, "cli.mjs");
    assert.notEqual(statSync(executable).mode & 0o111, 0);
    const smoke = spawnSync(executable, [], { cwd: packageRoot, encoding: "utf8" });
    assert.equal(smoke.status, 1);
    assert.match(smoke.stderr, /usage: pi-intercom/);
  } finally {
    rmSync(temp, { recursive: true, force: true });
  }
});

import test from "node:test";
import assert from "node:assert/strict";
import {
  DISCOVERY_TIMEOUT_MS,
  discoverRemoteAgent,
  listMachineAgents,
  parseCrossMachineTarget,
  parseRemoteAgents,
  parseSavedMachines,
} from "./cross-machine-discovery.ts";
import type { CommandRunner } from "./cross-machine-transport.ts";

const fakeSessionId = "00000000-0000-4000-8000-000000000001";

function machineList(rows: Array<{ label: string; target: string; enabled: boolean }>): string {
  return JSON.stringify(rows);
}

function agentList(rows: Array<{ name: string; sessionId?: string }>): string {
  return JSON.stringify({ id: "cli:agent:list", result: { agents: rows.map((row) => ({
    agent: "pi",
    name: row.name,
    ...(row.sessionId ? {
      agent_session: {
        agent: "pi",
        kind: "path",
        source: "herdr:pi",
        value: `/home/user/.pi/agent/sessions/session_${row.sessionId}.jsonl`,
      },
    } : {}),
  })) } });
}

const machines = machineList([
  { label: "laptop", target: "laptop.example", enabled: true },
  { label: "Workstation", target: "workstation.example", enabled: true },
  { label: "disabled", target: "disabled.example", enabled: false },
]);
const agents = agentList([{ name: "reviewer", sessionId: fakeSessionId }]);

test("parses the supported explicit remote address forms", () => {
  assert.deepEqual(parseCrossMachineTarget("reviewer@Workstation"), {
    agentTarget: "reviewer",
    machineLabel: "Workstation",
  });
  assert.deepEqual(parseCrossMachineTarget(`${fakeSessionId}@workstation`), {
    agentTarget: fakeSessionId,
    machineLabel: "workstation",
  });
});

test("parses current Herdr machine and agent list schemas", () => {
  assert.deepEqual(parseSavedMachines(machines), [
    { label: "laptop", target: "laptop.example", enabled: true },
    { label: "Workstation", target: "workstation.example", enabled: true },
    { label: "disabled", target: "disabled.example", enabled: false },
  ]);
  assert.deepEqual(parseRemoteAgents(agents), [{ name: "reviewer", sessionId: fakeSessionId }]);
});

test("listMachineAgents turns Herdr's debug error into a readable reason with an update hint", async () => {
