import test from "node:test";
import assert from "node:assert/strict";
import { isMessage, messageDeliveryFingerprint } from "./protocol.ts";
import type { CrossMachineProvenance, Message } from "../types.ts";

const origin = { name: "worker", sessionId: "origin-session", machine: "laptop" };
const provenance: CrossMachineProvenance = {
  type: "ssh-relay",
  version: 1,
  trust: "ssh-asserted",
  origin,
};

function messageWith(crossMachine: unknown): unknown {
  return {
    id: "message-1",
    timestamp: 1,
    crossMachine,
    content: { text: "hello" },
  };
}

test("protocol validates the complete SSH relay provenance discriminator and origin", () => {
  assert.equal(isMessage(messageWith(provenance)), true);

  const invalid: unknown[] = [
    { ...provenance, type: "ssh" },
    { ...provenance, type: undefined },
    { ...provenance, version: 2 },
    { ...provenance, version: undefined },
    { ...provenance, trust: "verified" },
    { ...provenance, trust: undefined },
    { ...provenance, origin: undefined },
    { ...provenance, origin: { ...origin, name: 1 } },
    { ...provenance, origin: { ...origin, sessionId: 1 } },
    { ...provenance, origin: { ...origin, machine: 1 } },
  ];
  for (const crossMachine of invalid) {
    assert.equal(isMessage(messageWith(crossMachine)), false, JSON.stringify(crossMachine));
  }

  assert.equal(isMessage({
    ...(messageWith(provenance) as Record<string, unknown>),
    provenance: {
      type: "extension_outbox",
      extensionId: "extension-id",
      extensionName: "Extension",
      requestId: "request-id",
    },
  }), true);
});

test("broker replay fingerprints distinguish every asserted origin field", () => {
  const message = messageWith(provenance) as Message;
  const original = messageDeliveryFingerprint(message, "receiver-session");
  for (const [field, value] of [["name", "other"], ["sessionId", "other"], ["machine", "other"]] as const) {
    const changed: Message = {
      ...message,
      crossMachine: { ...provenance, origin: { ...origin, [field]: value } },
    };
    assert.notEqual(messageDeliveryFingerprint(changed, "receiver-session"), original);
  }
});

import test from "node:test";
import assert from "node:assert/strict";
import net from "node:net";
import { once } from "node:events";
import { createMessageReader, writeMessage } from "./framing.ts";

function framePayload(payload: Buffer): Buffer {
  const header = Buffer.alloc(4);
  header.writeUInt32BE(payload.length, 0);
  return Buffer.concat([header, payload]);
}

test("createMessageReader handles normal fragmented frames", () => {
  const messages: unknown[] = [];
  const errors: Error[] = [];
  const reader = createMessageReader(
    (message) => messages.push(message),
    (error) => errors.push(error),
    64,
  );
  const frameA = framePayload(Buffer.from(JSON.stringify({ type: "one" }), "utf-8"));
  const frameB = framePayload(Buffer.from(JSON.stringify({ type: "two" }), "utf-8"));
  const combined = Buffer.concat([frameA, frameB]);

  reader(combined.subarray(0, 2));
  reader(combined.subarray(2, 7));
  reader(combined.subarray(7));

  assert.deepEqual(messages, [{ type: "one" }, { type: "two" }]);
  assert.deepEqual(errors, []);
});

test("createMessageReader reassembles a fragmented frame after a header-boundary fast-path frame", () => {
  const messages: unknown[] = [];
  const errors: Error[] = [];
  const reader = createMessageReader(
    (message) => messages.push(message),
    (error) => errors.push(error),
    64,
  );
  const frameA = framePayload(Buffer.from(JSON.stringify({ a: 1 }), "utf-8"));
  const frameB = framePayload(Buffer.from(JSON.stringify({ bb: "1234567890" }), "utf-8"));

  reader(frameA.subarray(0, 4)); // chunk ends exactly at the end of frame A's header
  reader(frameA.subarray(4)); // frame A's payload arrives whole (zero-copy fast path)
  reader(frameB.subarray(0, 6)); // frame B header + partial payload (buffered path)
  reader(frameB.subarray(6));

  assert.deepEqual(messages, [{ a: 1 }, { bb: "1234567890" }]);
  assert.deepEqual(errors, []);
});

test("createMessageReader rejects an oversized declared frame", () => {
  const messages: unknown[] = [];
  const errors: Error[] = [];
  const reader = createMessageReader(
    (message) => messages.push(message),
    (error) => errors.push(error),
    8,
  );
  const oversizedFrame = framePayload(Buffer.from(JSON.stringify({ text: "too large" }), "utf-8"));

  reader(oversizedFrame);

  assert.deepEqual(messages, []);
  assert.equal(errors.length, 1);
  assert.match(errors[0].message, /Intercom frame length \d+ exceeds maximum 8 bytes/);
});

test("createMessageReader rejects an oversized frame before retaining same-chunk payload bytes", () => {
  const messages: unknown[] = [];
  const errors: Error[] = [];
  const reader = createMessageReader(
    (message) => messages.push(message),
    (error) => errors.push(error),
    8,
  );
  const header = Buffer.alloc(4);
  header.writeUInt32BE(9, 0);

  reader(Buffer.concat([header, Buffer.alloc(1024 * 1024)]));

  assert.deepEqual(messages, []);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, "Intercom frame length 9 exceeds maximum 8 bytes");
});

test("createMessageReader rejects a partial oversized frame before buffering the payload", () => {
  const messages: unknown[] = [];
  const errors: Error[] = [];
  const reader = createMessageReader(
    (message) => messages.push(message),
    (error) => errors.push(error),
    8,
  );
  const header = Buffer.alloc(4);
  header.writeUInt32BE(9, 0);

  reader(header);

  assert.deepEqual(messages, []);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, "Intercom frame length 9 exceeds maximum 8 bytes");
});

test("writeMessage emits frames accepted by createMessageReader", () => {
  const chunks: Buffer[] = [];
  const socket = { write: (chunk: Buffer) => chunks.push(chunk) };
  const messages: unknown[] = [];
  const reader = createMessageReader((message) => messages.push(message), assert.fail, 64);

  writeMessage(socket as never, { ok: true });
  reader(Buffer.concat(chunks));

  assert.deepEqual(messages, [{ ok: true }]);
});

test("writeMessage drops a peer that stopped reading instead of queueing for it without bound", async () => {
  const server = net.createServer().listen(0, "127.0.0.1");
  await once(server, "listening");
  const peer = net.connect((server.address() as net.AddressInfo).port, "127.0.0.1");
  peer.pause();
  const [socket] = (await once(server, "connection")) as [net.Socket];
  const message = { text: "x".repeat(512 * 1024) };
  try {
    let writes = 0;
    while (!socket.destroyed && writes < 100) {
      writeMessage(socket, message);
      writes += 1;
    }

    assert.equal(socket.destroyed, true, `socket still open after ${writes} unread 512 KiB frames`);
  } finally {
    socket.destroy();
    peer.destroy();
    server.close();
  }
});

import test from "node:test";
import assert from "node:assert/strict";

import { visibleWidth } from "@earendil-works/pi-tui";
import { HandoverPicker, type HandoverPickerResult, type RemoteSessionLister } from "../ui/handover-picker.ts";
import { SessionListOverlay, type SessionListSelection } from "../ui/session-list.ts";
import type { SessionInfo } from "../types.ts";

const theme = { fg: (_name: string, text: string) => text, bold: (text: string) => text };
const KEYS: Record<string, string> = {
  "tui.select.up": "\x1b[A",
  "tui.select.down": "\x1b[B",
  "tui.select.confirm": "\r",
  "tui.select.cancel": "\x1b",
  "tui.input.tab": "\t",
  "tui.editor.deleteCharBackward": "\x7f",
};
const keybindings = {
  matches: (data: string, id: string) => KEYS[id] === data,
  getKeys: (id: string) => [id.split(".").pop()!],
};

function session(id: string, name: string, extra: Partial<SessionInfo> = {}): SessionInfo {
  return { id, name, cwd: `/work/${name}`, model: "model", pid: 1, startedAt: 0, lastActivity: 0, ...extra };
}

const self = session("self-0000", "planner");
const roster = [
  self,
  session("subagent-worker-run-1", "worker: You are the writer for lane x"),
  session("unnamed-00", "subagent-chat-unnamed", { runtimeFallbackAlias: true, lastActivity: 1 }),
  session("adapter-00", "adapter", { lastActivity: 2 }),
];
const noRemote: RemoteSessionLister = {
  listMachines: async () => assert.fail("remote listing must not run on open"),
  listAgents: async () => [],
};

function open(options: { lister?: RemoteSessionLister; preselectSessionId?: string } = {}) {
  const results: Array<HandoverPickerResult | undefined> = [];
  const picker = new HandoverPicker(
    { requestRender() {} } as any,
    theme as any,
    keybindings as any,
    { currentSession: self, sessions: roster, lister: options.lister ?? noRemote, preselectSessionId: options.preselectSessionId },
    (result) => results.push(result),
  );
  const press = (...keys: string[]) => keys.forEach((key) => picker.handleInput(KEYS[key] ?? key));
  return { picker, results, press, text: () => picker.render(88).join("\n") };
}

test("handover picker lists local peers without self or subagent children", () => {
  const { text, press, results } = open();
  assert.doesNotMatch(text(), /planner|You are the writer/);
  assert.match(text(), /adapter \(adapter-\)[\s\S]*subagent-chat-unnamed/);
  press("tui.select.confirm");
  assert.equal(results[0]?.target.kind === "local" && results[0].target.session.id, "adapter-00");
});

test("handover picker returns the next task typed in the task field", () => {
  const { press, results } = open({ preselectSessionId: "unnamed-00" });
  press("port", " the fix", "tui.select.confirm");
  assert.deepEqual(results, [{ target: { kind: "local", session: roster[2] }, goal: "port the fix" }]);
});

test("handover picker accepts pasted and Kitty-encoded next-task text", () => {
  const { press, results } = open();
  press("tui.input.tab", "\x1b[200~port the fix\x1b[201~", "\x1b[32u", "\x1b[97u", "tui.select.confirm");
  assert.equal(results[0]?.goal, "port the fix a");
});

test("session list starts a handover on plain or Kitty-encoded h and messages on Enter", () => {
  for (const [key, action] of [["h", "handover"], ["\x1b[104u", "handover"], ["\r", "message"]] as const) {
    const selections: Array<SessionListSelection | undefined> = [];
    new SessionListOverlay(theme as any, keybindings as any, self, [roster[3]!], (selection) => selections.push(selection)).handleInput(key);
    assert.deepEqual(selections, [{ session: roster[3], action }], key);
  }
});

test("handover picker fetches other machines on demand and targets a remote session by id", async () => {
  const sessionId = "00000000-0000-4000-8000-000000000001";
  const lister: RemoteSessionLister = {
    listMachines: async () => [
      { label: "workmac", target: "10.0.0.1", enabled: true },
      { label: "macmini", target: "10.0.0.2", enabled: true },
      { label: "off", target: "10.0.0.3", enabled: false },
    ],
    listAgents: async (machine) => {
      if (machine.label === "macmini") throw new Error(`Saved Herdr machine "macmini" is unreachable: ${"slow ".repeat(20)}end-of-error.`);
      return [{ name: sessionId, sessionId, cwd: "/work/remote", status: "idle" }];
    },
  };
  const { press, results, text } = open({ lister });
  press("tui.select.down", "tui.select.down", "tui.select.down", "tui.select.confirm");
  await new Promise((resolve) => setImmediate(resolve));

  assert.match(text(), /00000000@workmac · idle/);
  assert.match(text(), /Saved Herdr machine "macmini" is unreachable/);
  assert.match(text(), /end-of-error\./, "long machine errors wrap instead of being cut off");
  assert.doesNotMatch(text(), /off/);
  press("tui.select.down", "tui.select.confirm");
  assert.deepEqual(results, [{ target: { kind: "remote", target: `${sessionId}@workmac` }, goal: undefined }]);
});

test("handover picker keeps the highlighted remote session when an earlier machine answers later", async () => {
  let answerSlow: (agents: Array<{ name: string }>) => void = () => {};
  const lister: RemoteSessionLister = {
    listMachines: async () => [
      { label: "slow", target: "10.0.0.1", enabled: true },
      { label: "fast", target: "10.0.0.2", enabled: true },
    ],
    listAgents: (machine) => machine.label === "fast"
      ? Promise.resolve([{ name: "fast-agent" }])
      : new Promise((resolve) => { answerSlow = resolve; }),
  };
  const { press, results } = open({ lister });
  press("tui.select.down", "tui.select.down", "tui.select.down", "tui.select.confirm");
  await new Promise((resolve) => setImmediate(resolve));
  press("tui.select.down");
  answerSlow([{ name: "slow-agent" }]);
  await new Promise((resolve) => setImmediate(resolve));
  press("tui.select.confirm");
  assert.deepEqual(results, [{ target: { kind: "remote", target: "fast-agent@fast" }, goal: undefined }]);
});

test("handover picker renders lines at the declared overlay width", () => {
  const { picker, press } = open();
  for (const focus of ["list", "task"]) {
    for (const width of [1, 2, 20, 50, 88, 120]) {
      for (const line of picker.render(width)) assert.equal(visibleWidth(line), Math.min(width, 88), `${focus} ${width}`);
    }
    press("tui.input.tab", "a long next task that does not fit in a narrow overlay");
  }
});

import test from "node:test";
import assert from "node:assert/strict";
import { chmodSync, mkdtempSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  ensureIntercomRuntimeDir,
  getAgentDirPath,
  getBrokerConnectTarget,
  getBrokerListenTarget,
  getBrokerPortFilePath,
  getBrokerSocketPath,
  getIntercomDirPath,
  INTERCOM_DIR_MODE,
  INTERCOM_RUNTIME_FILE_MODE,
  INTERCOM_TCP_HOST,
  restrictIntercomRuntimeFile,
  shouldUseWindowsTcpTransport,
} from "./paths.ts";

test("getAgentDirPath defaults to the pi agent directory under home", () => {
  assert.equal(getAgentDirPath({}, "/home/rcroh"), join("/home/rcroh", ".pi/agent"));
});

test("getAgentDirPath honors PI_CODING_AGENT_DIR", () => {
  assert.equal(getAgentDirPath({ PI_CODING_AGENT_DIR: "/tmp/pi-agent" }, "/home/rcroh"), "/tmp/pi-agent");
});

test("getAgentDirPath resolves relative PI_CODING_AGENT_DIR values from the caller cwd", () => {
  const cwd = join(tmpdir(), "workspace", "project");
  assert.equal(
    getAgentDirPath({ PI_CODING_AGENT_DIR: "relative-agent" }, "/home/rcroh", cwd),
    join(cwd, "relative-agent"),
  );
});

test("getIntercomDirPath points at the intercom runtime directory under the agent dir", () => {
  assert.equal(getIntercomDirPath("/tmp/pi-agent"), join("/tmp/pi-agent", "intercom"));
});

test("getBrokerSocketPath uses named pipe on Windows", () => {
  const pipePath = getBrokerSocketPath("win32", "C:/Users/rcroh/.pi/agent");
  assert.match(pipePath, /^\\\\\.\\pipe\\pi-intercom-/);
  assert.doesNotMatch(pipePath, /broker\.sock$/);
});

test("getBrokerSocketPath uses broker.sock under PI_CODING_AGENT_DIR on non-Windows", () => {
  const socketPath = getBrokerSocketPath("linux", "/tmp/pi-agent");
  assert.equal(socketPath, join("/tmp/pi-agent", "intercom", "broker.sock"));
});

test("Windows TCP transport is opt-in", () => {
  assert.equal(shouldUseWindowsTcpTransport("win32", {}), false);
  assert.equal(shouldUseWindowsTcpTransport("win32", { PI_INTERCOM_TRANSPORT: "tcp" }), true);
  assert.equal(shouldUseWindowsTcpTransport("win32", { PI_INTERCOM_TCP: "1" }), true);
  assert.equal(shouldUseWindowsTcpTransport("linux", { PI_INTERCOM_TRANSPORT: "tcp" }), false);
});

test("getBrokerListenTarget uses dynamic localhost TCP only when opted in on Windows", () => {
  assert.deepEqual(getBrokerListenTarget("win32", { PI_INTERCOM_TRANSPORT: "tcp" }), {
    transport: "tcp",
    host: INTERCOM_TCP_HOST,
    port: 0,
  });
  assert.equal(getBrokerListenTarget("win32", {}), getBrokerSocketPath("win32", getAgentDirPath({})));
});

test("getBrokerConnectTarget reads opt-in Windows TCP endpoint from intercom state", () => {
  const root = mkdtempSync(join(tmpdir(), "pi-intercom-paths-"));
  const intercomDir = join(root, "intercom");

  try {
    ensureIntercomRuntimeDir(intercomDir, "win32");
    writeFileSync(getBrokerPortFilePath(intercomDir), JSON.stringify({
      transport: "tcp",
      host: "127.0.0.1",
      port: 41234,
      stateId: "state-1",
    }));
    assert.deepEqual(getBrokerConnectTarget("win32", { PI_INTERCOM_TRANSPORT: "tcp" }, intercomDir), {
      transport: "tcp",
      host: "127.0.0.1",
      port: 41234,
      stateId: "state-1",
    });
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("getBrokerConnectTarget rejects non-local TCP endpoint hosts", () => {
  const root = mkdtempSync(join(tmpdir(), "pi-intercom-paths-"));
  const intercomDir = join(root, "intercom");

  try {
    ensureIntercomRuntimeDir(intercomDir, "win32");
    writeFileSync(getBrokerPortFilePath(intercomDir), JSON.stringify({
      transport: "tcp",
      host: "10.0.0.5",
      port: 41234,
      stateId: "state-1",
    }));
    assert.throws(
      () => getBrokerConnectTarget("win32", { PI_INTERCOM_TRANSPORT: "tcp" }, intercomDir),
      /Invalid intercom TCP endpoint/,
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("ensureIntercomRuntimeDir creates and repairs restrictive Unix directory permissions", { skip: process.platform === "win32" }, () => {
  const root = mkdtempSync(join(tmpdir(), "pi-intercom-paths-"));
  const intercomDir = join(root, "intercom");

  try {
    ensureIntercomRuntimeDir(intercomDir, "linux");
    assert.equal(statSync(intercomDir).mode & 0o777, INTERCOM_DIR_MODE);

    chmodSync(intercomDir, 0o755);
    ensureIntercomRuntimeDir(intercomDir, "linux");
    assert.equal(statSync(intercomDir).mode & 0o777, INTERCOM_DIR_MODE);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("restrictIntercomRuntimeFile applies restrictive Unix file permissions", { skip: process.platform === "win32" }, () => {
  const root = mkdtempSync(join(tmpdir(), "pi-intercom-paths-"));
  const filePath = join(root, "broker.pid");

  try {
    writeFileSync(filePath, "123", { mode: 0o644 });
    restrictIntercomRuntimeFile(filePath, "linux");
    assert.equal(statSync(filePath).mode & 0o777, INTERCOM_RUNTIME_FILE_MODE);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("runtime permission helpers skip chmod on Windows paths", () => {
  const root = mkdtempSync(join(tmpdir(), "pi-intercom-paths-"));
  const filePath = join(root, "broker.pid");

  try {
    ensureIntercomRuntimeDir(root, "win32");
    writeFileSync(filePath, "123");
    assert.doesNotThrow(() => restrictIntercomRuntimeFile(filePath, "win32"));
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
